compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 47 do while direct") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(value, Add, 1);
        Skip(2);
        Modify Global Variable(value, Add, 10);
        Loop If(Compare(Global.value, <, 2));
        //__label_break_2__:
    }
}

rule ("issue 47 do while conditional") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(value, Add, 1);
        Skip If(Compare(Global.value, ==, 1), 2);
        Modify Global Variable(value, Add, 10);
        Loop If(Compare(Global.value, <, 2));
        //__label_break_3__:
    }
}

rule ("issue 47 do while nested") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(value, Add, 1);
        Skip(1);
        Loop If(Compare(Global.value, <, 2));
        //__label_break_4__:
        Modify Global Variable(value, Add, 10);
        Loop If(Compare(Global.value, <, 2));
    }
}

rule ("issue 47 do while structured tail") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(value, Add, 1);
        Skip(5);
        If(Compare(Global.value, ==, 1));
            Modify Global Variable(value, Add, 2);
        End;
        Modify Global Variable(value, Add, 10);
        Loop If(Compare(Global.value, <, 2));
        //__label_break_5__:
    }
}

